/// expansion.library keeps it (not packed: it follows `#pragma pack()`).
#[repr(C)]
pub struct PCICapability {
    pub Node: MinNode,
    /// PCI_CAPABILITYID_*.
    pub Type: u32,
    /// The library's structure size, header included.
    pub Size: u32,
    /// Where the capability starts in configuration space.
    pub CapOffset: u32,
}

/// expansion/pci.h: one base address range of a PCI device.
#[repr(C, packed(2))]
pub struct PCIResourceRange {
    pub Node: Node,
    pub BaseAddress: u32,
    pub Size: u32,
    pub Physical: u32,
    pub Flags: u32,
}

// Layouts measured from the SDK 54.25 headers with ppc-amigaos-gcc 15.3.0.
#[cfg(target_os = "amigaos")]
const _: () = {
    assert!(core::mem::size_of::<Node>() == 14);
    assert!(core::mem::size_of::<PCIResourceRange>() == 30);
    assert!(core::mem::offset_of!(PCIResourceRange, BaseAddress) == 14);
    assert!(core::mem::offset_of!(PCIResourceRange, Physical) == 22);
    assert!(core::mem::offset_of!(PCIResourceRange, Flags) == 26);
    assert!(core::mem::offset_of!(PCIDevice, ReadConfigByte) == 76);
    assert!(core::mem::offset_of!(PCIDevice, InByte) == 100);
    assert!(core::mem::offset_of!(PCIDevice, GetResourceRange) == 124);
    assert!(core::mem::size_of::<PCIDevice>() == 228);
    assert!(core::mem::size_of::<InterruptNode>() == 22);
    assert!(core::mem::offset_of!(InterruptNode, is_Data) == 14);
    assert!(core::mem::offset_of!(InterruptNode, is_Code) == 18);
};

